import { Children, isValidElement, useEffect, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from 'react'
import { Pause, Play, RotateCcw, SkipBack, SkipForward } from 'lucide-react'

/**
 * A step-by-step animation from a ```anim block (JSON) in an answer or lesson: an array with
 * pointers, a grid, a hash map, a stack or queue, a flow of stages, and optionally the code with
 * the current line and variables. Frames are generated by running the real algorithm
 * (tools/anim/build.py), so what you watch is what the code does.
 */

type Mark = 'hit' | 'done' | 'bad' | 'cur'
type Val = string | number | boolean | null

export interface AnimFrame {
  note?: string
  line?: number
  vars?: Record<string, Val>
  array?: { label?: string; values: Val[]; pointers?: Record<string, number>; range?: [number, number]; marks?: Record<string, Mark> }
  map?: { label?: string; entries: [string, Val][]; hit?: string }
  stack?: { label?: string; items: Val[]; kind?: 'stack' | 'queue' }
  grid?: { cells: Val[][]; marks?: Record<string, Mark> }
  stage?: number
}

export interface AnimSpec {
  title?: string
  code?: string[]
  stages?: string[]
  /** Grid cell value → colour slot c1..c5. */
  colors?: Record<string, string>
  frames: AnimFrame[]
}

export function animSource(children: ReactNode): string | null {
  const code = Children.toArray(children)[0]
  if (!isValidElement<{ className?: string; children?: ReactNode }>(code)) return null
  if (!(code.props.className ?? '').includes('language-anim')) return null
  return Children.toArray(code.props.children).join('').trim()
}

export function AnimBlock({ source }: { source: string }) {
  const spec = useMemo(() => {
    try {
      const s = JSON.parse(source) as AnimSpec
      return s.frames?.length ? s : null
    } catch {
      return null
    }
  }, [source])
  if (!spec) return <pre>{source}</pre>
  return <Anim spec={spec} />
}

const SPEEDS = [0.5, 1, 2]
const show = (v: Val) => (v === null ? 'null' : typeof v === 'boolean' ? String(v) : String(v))

export function Anim({ spec }: { spec: AnimSpec }) {
  const n = spec.frames.length
  const [at, setAt] = useState(0)
  const [playing, setPlaying] = useState(false)
  const [speed, setSpeed] = useState(1)
  const timer = useRef<number | null>(null)
  const f = spec.frames[at]
  const prev = at > 0 ? spec.frames[at - 1] : undefined

  useEffect(() => {
    if (!playing) return
    if (at >= n - 1) {
      setPlaying(false)
      return
    }
    timer.current = window.setTimeout(() => setAt((a) => Math.min(n - 1, a + 1)), 1400 / speed)
    return () => {
      if (timer.current) window.clearTimeout(timer.current)
    }
  }, [playing, at, n, speed])

  const go = (i: number) => setAt(Math.max(0, Math.min(n - 1, i)))
  const toggle = () => {
    if (at >= n - 1) setAt(0)
    setPlaying((p) => !p)
  }
  const onKey = (e: KeyboardEvent) => {
    if (e.key === 'ArrowRight') { e.preventDefault(); setPlaying(false); go(at + 1) }
    if (e.key === 'ArrowLeft') { e.preventDefault(); setPlaying(false); go(at - 1) }
    if (e.key === ' ') { e.preventDefault(); toggle() }
  }

  const visual = (
    <div className="anim-visual">
      {spec.stages && <Stages stages={spec.stages} at={f.stage ?? -1} />}
      {f.array && <ArrayView a={f.array} />}
      {f.grid && <GridView g={f.grid} colors={spec.colors ?? {}} />}
      <div className="anim-side">
        {f.map && <MapView m={f.map} />}
        {f.stack && <StackView s={f.stack} />}
        {f.vars && <Vars vars={f.vars} prev={prev?.vars} />}
      </div>
    </div>
  )

  return (
    <figure className="anim" tabIndex={0} onKeyDown={onKey} aria-label={spec.title ?? 'Animation'}>
      {spec.title && <figcaption className="anim-title">{spec.title}</figcaption>}
      <div className={`anim-body ${spec.code ? 'with-code' : ''}`}>
        {visual}
        {spec.code && <Code lines={spec.code} line={f.line} />}
      </div>
      <p className="anim-note" aria-live="polite">
        <span className="anim-step num">{at + 1}</span>
        {f.note}
      </p>
      <div className="anim-controls">
        <button className="btn sm ghost" onClick={() => { setPlaying(false); setAt(0) }} aria-label="Restart">
          <RotateCcw size={14} />
        </button>
        <button className="btn sm" onClick={() => { setPlaying(false); go(at - 1) }} disabled={at === 0} aria-label="Previous step">
          <SkipBack size={14} />
        </button>
        <button className="btn sm primary anim-play" onClick={toggle} aria-label={playing ? 'Pause' : 'Play'}>
          {playing ? <Pause size={14} /> : <Play size={14} />} {playing ? 'Pause' : at >= n - 1 ? 'Replay' : 'Play'}
        </button>
        <button className="btn sm" onClick={() => { setPlaying(false); go(at + 1) }} disabled={at >= n - 1} aria-label="Next step">
          <SkipForward size={14} />
        </button>
        <input
          type="range"
          className="anim-scrub"
          min={0}
          max={n - 1}
          value={at}
          onChange={(e) => { setPlaying(false); setAt(Number(e.target.value)) }}
          aria-label="Step"
        />
        <span className="muted num anim-count">
          {at + 1}/{n}
        </span>
        <div className="seg anim-speed" role="group" aria-label="Speed">
          {SPEEDS.map((s) => (
            <button key={s} aria-pressed={speed === s} onClick={() => setSpeed(s)}>
              {s}×
            </button>
          ))}
        </div>
      </div>
    </figure>
  )
}

function ArrayView({ a }: { a: NonNullable<AnimFrame['array']> }) {
  // Cells share one width, wide enough for the longest value (e.g. a bucket chain "Aa → BB").
  const CELL = Math.max(46, ...a.values.map((v) => show(v).length * 9 + 18))
  const pointers = Object.entries(a.pointers ?? {})
  // Pointers on the same index stack downwards instead of overlapping.
  const depth = new Map<string, number>()
  const used = new Map<number, number>()
  for (const [name, idx] of pointers) {
    const d = used.get(idx) ?? 0
    depth.set(name, d)
    used.set(idx, d + 1)
  }
  const rows = Math.max(1, ...Array.from(used.values()))
  return (
    <div className="anim-array-wrap">
      {a.label && <div className="anim-label">{a.label}</div>}
      <div className="anim-array" style={{ width: a.values.length * CELL }}>
        {a.values.map((v, i) => {
          const inRange = a.range && i >= a.range[0] && i <= a.range[1]
          const mark = a.marks?.[String(i)]
          return (
            <div key={i} className={`anim-cell ${inRange ? 'in' : ''} ${mark ?? ''}`} style={{ width: CELL }}>
              <span className="anim-idx">{i}</span>
              <span className="anim-val">{show(v)}</span>
            </div>
          )
        })}
        <div className="anim-pointers" style={{ height: rows * 22 + 4 }}>
          {pointers.map(([name, idx]) => (
            <span
              key={name}
              className="anim-ptr"
              style={{ transform: `translateX(${idx * CELL + CELL / 2}px)`, top: (depth.get(name) ?? 0) * 22 }}
            >
              ▲ {name}
            </span>
          ))}
        </div>
      </div>
    </div>
  )
}

function GridView({ g, colors }: { g: NonNullable<AnimFrame['grid']>; colors: Record<string, string> }) {
  return (
    <div className="anim-grid" style={{ gridTemplateColumns: `repeat(${g.cells[0]?.length ?? 1}, 36px)` }}>
      {g.cells.flatMap((row, r) =>
        row.map((v, c) => {
          const mark = g.marks?.[`${r},${c}`]
          return (
            <div key={`${r},${c}`} className={`anim-gcell ${colors[show(v)] ?? ''} ${mark ?? ''}`}>
              {show(v)}
            </div>
          )
        }),
      )}
    </div>
  )
}

function MapView({ m }: { m: NonNullable<AnimFrame['map']> }) {
  return (
    <div className="anim-box">
      <div className="anim-label">{m.label ?? 'map'}</div>
      <div className="anim-map">
        {m.entries.length === 0 && <span className="muted">empty</span>}
        {m.entries.map(([k, v]) => (
          <span key={k} className={`anim-entry ${m.hit === k ? 'hit' : ''}`}>
            <b>{k}</b>
            {v !== null && v !== '' && <> → {show(v)}</>}
          </span>
        ))}
      </div>
    </div>
  )
}

function StackView({ s }: { s: NonNullable<AnimFrame['stack']> }) {
  const queue = s.kind === 'queue'
  return (
    <div className="anim-box">
      <div className="anim-label">{s.label ?? (queue ? 'queue (front → back)' : 'stack (top on the right)')}</div>
      <div className="anim-stack">
        {s.items.length === 0 && <span className="muted">empty</span>}
        {s.items.map((v, i) => (
          <span key={`${i}-${show(v)}`} className={`anim-item ${(!queue && i === s.items.length - 1) || (queue && i === 0) ? 'edge' : ''}`}>
            {show(v)}
          </span>
        ))}
      </div>
    </div>
  )
}

function Vars({ vars, prev }: { vars: Record<string, Val>; prev?: Record<string, Val> }) {
  return (
    <div className="anim-box">
      <div className="anim-label">variables</div>
      <div className="anim-vars">
        {Object.entries(vars).map(([k, v]) => (
          <span key={`${k}=${show(v)}`} className={`anim-var ${prev && prev[k] !== v ? 'changed' : ''}`}>
            {k} = <b>{show(v)}</b>
          </span>
        ))}
      </div>
    </div>
  )
}

function Stages({ stages, at }: { stages: string[]; at: number }) {
  return (
    <ol className="anim-stages">
      {stages.map((s, i) => (
        <li key={i} className={i < at ? 'done' : i === at ? 'on' : ''}>
          <span className="anim-stage-n">{i + 1}</span>
          {s}
        </li>
      ))}
    </ol>
  )
}

function Code({ lines, line }: { lines: string[]; line?: number }) {
  return (
    <pre className="anim-code">
      {lines.map((l, i) => (
        <div key={i} className={`anim-line ${line === i + 1 ? 'on' : ''}`}>
          <span className="anim-ln">{i + 1}</span>
          {l || ' '}
        </div>
      ))}
    </pre>
  )
}
